def build_qa(rows: list[tuple[str, str]], rng: random.Random, pairs: list[dict[str, Any]], seen: set) -> None:
    by_answer: dict[str, list[tuple[int, str, str]]] = defaultdict(list)
    for index, (question, answer) in enumerate(rows):
        by_answer[norm(answer)].append((index, question, answer))

    for indices in by_answer.values():
        if len(indices) < 2:
            continue
        for (i, qi, ai), (j, qj, _) in itertools.combinations(indices, 2):
            if sum(1 for p in pairs if p["category"] == "same_answer") >= QA_COUNTS["same_answer"]:
                break
            if jaccard(qi, qj) < 0.3:
                continue
            add(pairs, seen, {
